/**
 * Lightweight event store.
 * Lets HomePage navigate to /result at 99% while the CSV fetch keeps running.
 * ResultPage subscribes on mount; if data is already there it fires immediately.
 */
let _pending = null
const _subscribers = []

/** Called by HomePage when the fetch resolves (or rejects with an error). */
export function publishResult(data) {
  _pending = data
  _subscribers.splice(0).forEach(fn => fn(data))
}

/**
 * Called by ResultPage on mount.
 * If data has already arrived the callback fires synchronously and clears the store.
 * Otherwise it is queued until publishResult is called.
 */
export function subscribeResult(fn) {
  if (_pending !== null) {
    const d = _pending
    _pending = null
    fn(d)
  } else {
    _subscribers.push(fn)
  }
}

/** Called on ResultPage unmount — clears pending data and queued callbacks. */
export function cancelResult() {
  _pending = null
  _subscribers.length = 0
}
